<?php require __DIR__.'/../config/bootstrap.php';require_role('admin');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$action=$_POST['action']??'';if($action==='delete'){$d=$pdo->prepare('UPDATE courses SET is_active=0 WHERE id=?');$d->execute([(int)$_POST['id']]);flash('Course removed from the catalogue.');redirect('admin/courses.php');}else{$title=trim($_POST['title']??'');$desc=trim($_POST['description']??'');$inst=trim($_POST['instructor']??'');$duration=trim($_POST['duration']??'');if($title&&$desc){if($action==='edit'){$q=$pdo->prepare('UPDATE courses SET title=?,description=?,instructor=?,duration=? WHERE id=?');$q->execute([$title,$desc,$inst,$duration,(int)$_POST['id']]);}else{$q=$pdo->prepare('INSERT INTO courses(title,description,instructor,duration) VALUES(?,?,?,?)');$q->execute([$title,$desc,$inst,$duration]);}flash('Course saved.');redirect('admin/courses.php');}else $error='Title and description are required.';}}$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM courses WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}$courses=$pdo->query('SELECT * FROM courses ORDER BY created_at DESC')->fetchAll();$page_title='Manage courses';require __DIR__.'/../includes/header.php';?>
<h1 class="text-3xl font-bold">Manage courses</h1><div class="grid lg:grid-cols-2 gap-6 mt-6"><form method="post" class="bg-white border rounded-xl p-5 space-y-3"><h2 class="font-bold text-xl"><?= $edit?'Edit course':'Add course' ?></h2><?php if($error): ?><p class="text-red-600"><?= e($error) ?></p><?php endif; ?><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="<?= $edit?'edit':'add' ?>"><?php if($edit): ?><input type="hidden" name="id" value="<?= (int)$edit['id'] ?>"><?php endif; ?><input required name="title" placeholder="Course title" value="<?= e($edit['title']??'') ?>" class="w-full border p-3 rounded-lg"><textarea required name="description" placeholder="Course description" class="w-full border p-3 rounded-lg"><?= e($edit['description']??'') ?></textarea><input name="instructor" placeholder="Instructor" value="<?= e($edit['instructor']??'') ?>" class="w-full border p-3 rounded-lg"><input name="duration" placeholder="Duration" value="<?= e($edit['duration']??'') ?>" class="w-full border p-3 rounded-lg"><button class="bg-blue-700 text-white px-5 py-3 rounded-lg">Save course</button></form><div class="space-y-3"><?php foreach($courses as $c): ?><div class="bg-white border rounded-xl p-4 flex justify-between gap-3"><div><b><?= e($c['title']) ?></b><p class="text-sm text-slate-500"><?= $c['is_active']?'Active':'Archived' ?></p></div><div class="flex gap-3 text-sm"><a class="text-blue-700" href="?edit=<?= (int)$c['id'] ?>">Edit</a><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$c['id'] ?>"><button data-confirm="Remove this course from the catalogue?" class="text-red-600">Delete</button></form></div></div><?php endforeach; ?></div></div><?php require __DIR__.'/../includes/footer.php';?>
